// This JavaScript code is used for sorting and filtering the table data when the user clicks on the headers
function toggleSort(column, ascending) {
    let table = document.getElementById("dataTable");
    let rows = table.rows;

    // Loop through each row and set the sort direction if it's not the current one
    for (let i = 1; i < rows.length; i++) {
        if (rows[i].cells[column].innerHTML !== "" && rows[i].cells[column].innerHTML != '') { 
            if (ascending === true) {
                rows[i].cells[column].setAttribute("sort", "ascending");
            } else {
                rows[i].cells[column].setAttribute("sort", "descending");
            }
        }
    }

    // Update the table with the new data
    table.innerHTML = "";
    let tempData = [];
    for (let i = 1; i < rows.length; i++) {
        tempData.push(rows[i]);
    }
    let sortedData = tempData.sort((a, b) => {
        let val1 = parseFloat(a.cells[column].textContent);
        let val2 = parseFloat(b.cells[column].textContent);

        if (val1 < val2) return -1;
        if (val1 > val2) return 1;
        return 0;
    });
    let header = rows[0];
    table.innerHTML += header.outerHTML;
    for (let i = 0; i < sortedData.length; i++) {
        table.innerHTML += sortedData[i].outerHTML;
    }
}

